#define main joint_program_main
#include "joint.cpp"
#undef main
static json diagnose(const json& cfg,const json& r){auto begin=Clock::now();Matrix tb=mat(cfg["T_base_imu"]);Rbi=tb.topLeftCorner<3,3>();lever=tb.topRightCorner<3,1>();auto pts=loadpoints(r["source"]);for(auto&p:pts)p.head<3>()=Rbi.transpose()*(p.head<3>()-lever);auto src=cloud(pts);auto targetpts=loadpoints(r["target"]);Matrix sm=mat(r["seed"]);Vector3 center=sm.topRightCorner<3,1>();if(r.value("crop",true)){std::vector<Vector4>local;for(auto&p:targetpts)if((p.head<2>()-center.head<2>()).squaredNorm()<=14400&&p.z()>center.z()-10&&p.z()<center.z()+30)local.push_back(p);targetpts.swap(local);}auto pre=Clock::now();auto tar=cloud(targetpts);auto vm=vox(tar);double targetms=elapsed(pre);Pose3 base{sm};Pose3 T=base*Pose3(tb);Values values;values.insert(X(0),T);auto f=boost::make_shared<GP>(Pose3(),X(0),vm,src);f->set_num_threads(2);auto linear=Clock::now();auto hf=boost::dynamic_pointer_cast<HessianFactor>(f->linearize(values));Matrix A=hf->augmentedInformation();double linms=elapsed(linear);Matrix6 H=Matrix6::Zero(),Hr=H;Vector6 g=Vector6::Zero();json details=json::array();size_t no=0,large=0,horizontal=0,vertical=0;std::set<int>ids;std::vector<double>norms;double fdmax=0;Matrix4 tm=T.matrix();Matrix3 rot=T.rotation().matrix();for(size_t i=0;i<src->size();i++){Vector4 q=tm*src->points[i];int id=vm->lookup_voxel_index(vm->voxel_coord(q));if(id<0){no++;if(r.value("detail",false))details.push_back({{"i",i},{"associated",false}});continue;}ids.insert(id);auto&v=vm->lookup_voxel(id);Vector3 e=(v.mean-q).head<3>();Matrix3 C=(v.cov+tm*src->covs[i]*tm.transpose()).topLeftCorner<3,3>();Matrix3 W=C.inverse();Matrix J(3,6);J.leftCols<3>()=rot*skewSymmetric(src->points[i].head<3>());J.rightCols<3>()=-rot;Vector3 white=W.llt().matrixL().transpose()*e;double n=white.norm(),weight=n>2.795?2.795/n:1.;H+=J.transpose()*W*J;Hr+=weight*J.transpose()*W*J;g+=J.transpose()*W*e;large+=n>2.795;norms.push_back(n);Eigen::SelfAdjointEigenSolver<Matrix3> eig(v.cov.topLeftCorner<3,3>());double nz=std::abs(eig.eigenvectors()(2,0));horizontal+=nz>.8;vertical+=nz<.2;
 if(i<128){for(int j=0;j<6;j++){Vector6 d=Vector6::Zero();d(j)=1e-7;Vector3 a=(v.mean-T.retract(d).matrix()*src->points[i]).head<3>();Vector3 b=(v.mean-T.retract(-d).matrix()*src->points[i]).head<3>();fdmax=std::max(fdmax,((a-b)/2e-7-J.col(j)).cwiseAbs().maxCoeff());}}
 if(r.value("detail",false))details.push_back({{"i",i},{"associated",true},{"voxel_id",id},{"residual_m",arr(e)},{"white",arr(white)},{"J",arr(J)},{"W",arr(W)},{"huber_weight",weight},{"normal_abs_z",nz}});
 }
 Matrix adj=Pose3(tb).inverse().AdjointMap();Matrix Hb=adj.transpose()*H*adj;Matrix Hrb=adj.transpose()*Hr*adj;std::vector<int>a{3,4,2},b{0,1,5};Matrix3 Haa,Hab,Hbb;for(int i=0;i<3;i++)for(int j=0;j<3;j++){Haa(i,j)=Hb(a[i],a[j]);Hab(i,j)=Hb(a[i],b[j]);Hbb(i,j)=Hb(b[i],b[j]);}Matrix3 S=Haa-Hab*Hbb.completeOrthogonalDecomposition().solve(Hab.transpose());Matrix3 D=Matrix3::Identity();D(2,2)=.1;Matrix3 projection=D*Haa*D,schur=D*S*D;Eigen::SelfAdjointEigenSolver<Matrix3> es(projection),ss(schur);std::sort(norms.begin(),norms.end());json result={{"id",r["id"]},{"source_n",src->size()},{"target_n",tar->size()},{"native_support",f->num_inliers()},{"missing",no},{"large_white_norm",large},{"white_norm_p50",norms.empty()?0:norms[norms.size()/2]},{"unique_voxels",ids.size()},{"normal_horizontal_proxy",horizontal},{"normal_vertical_proxy",vertical},{"native_raw_error",f->error(values)},{"native_augmented_H",arr(A)},{"manual_H_max_diff",(H-A.topLeftCorner<6,6>()).cwiseAbs().maxCoeff()},{"manual_g_max_diff",(g+A.topRightCorner<6,1>()).cwiseAbs().maxCoeff()},{"raw_residual_fd_max",fdmax},{"base_H",arr(Hb)},{"base_H_robust",arr(Hrb)},{"XY_Lyaw_fixed_other_projection",arr(projection)},{"XY_Lyaw_schur_nuisance_eliminated",arr(schur)},{"projection_eigen",arr(es.eigenvalues())},{"schur_eigen",arr(ss.eigenvalues())},{"weak_projection_direction",arr(es.eigenvectors().col(0))},{"target_cov_voxel_ms",targetms},{"native_linearize_ms",linms},{"wall_ms",elapsed(begin)},{"points",details}};
 if(r.value("solve",false)){NonlinearFactorGraph graph;graph.push_back(boost::make_shared<Geometry>(f));gtsam_points::LevenbergMarquardtExtParams lm;lm.maxIterations=8;std::vector<json>its;lm.iterationHook=[&](size_t k,double e0,double e1){its.push_back({{"iteration",k},{"old",e0},{"new",e1}});};auto st=Clock::now();gtsam_points::LevenbergMarquardtOptimizerExt opt(graph,values,lm);auto solved=opt.optimize();auto p=solved.at<Pose3>(X(0))*Pose3(tb).inverse();result["independent_geometry_diagnostic_only"]={{"base_pose",arr(p.matrix())},{"iterations",its},{"iteration_count",opt.iterations()},{"wall_ms",elapsed(st)},{"no_IMU_Wheel",true}};}
 return result;
}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("cfg plan out");json cfg,plan;std::ifstream(argv[1])>>cfg;std::ifstream(argv[2])>>plan;std::ofstream out(argv[3]);for(auto&r:plan){auto z=diagnose(cfg,r);out<<z.dump()<<'\n';out.flush();std::cout<<r["id"]<<' '<<z["native_support"]<<'/'<<z["source_n"]<<'\n';}return 0;}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
